html:
{% set print_style = frappe.db.get_single_value("Print Settings", "print_style") %}
{% set color = frappe.db.get_value("Print Style", print_style, "custom_color") %}
<style>
    .pf-color {
        color: {{ color }};
    }

    .pf-font-size {
        font-size: 10px;
    }

    .pf-heading {
        font-size: 23px;
    }
    
    .pf-font-size-bg {
        font-size: 14px;
    }
</style>


<div class="pf-font">
    
    {% if letter_head %}
        {{ letter_head }}
    {% endif %}
    
    <h1 class="pf-heading pf-color">{{ doc.doctype }}</h1>
    
    <table class="pf-font-size-bg" style="width: 100%; line-height: 1;">
        <tbody>
            <tr>
                <td class="pf-color" style="width: 50%;">
                    <p>Number # الرقم</p>
                </td>
                <td style="width: 50%;">
                    <p>{{ doc.name }}</p>
                </td>
            </tr>
            <tr>
                <td class="pf-color" style="width: 50%;">
                    <p>Posting Date تاريخ</p>
                </td>
                <td style="width: 50%;">
                    <p>{{ doc.get_formatted("posting_date") }}</p>
                </td>
            </tr>
            <tr>
                <td class="pf-color" style="width: 50%;">
                    <p>Entry Type نوع القيد</p>
                </td>
                <td style="width: 50%;">
                    <p>{{ doc.voucher_type }}</p>
                </td>
            </tr>
        </tbody>
    </table>
    
    

{% set ns = namespace(show_vehicle=false) %}
{% for row in doc.accounts %}
    {% if row.vehicle %}
        {% set ns.show_vehicle = true %}
    {% endif %}
{% endfor %}

    
    <table class="pf-item-table pf-font-size" style="border: 3px solid {{ color }};">
        <thead>
            <tr style="background-color: {{ color }};">
                <th style="width: 5%;">No.<br>م</th>
                <th style="width: 35%;">Account<br>الحساب</th>
                <!-- Increase note/remarks width -->
                <th style="width: 30%;">Remarks<br>الملاحظات</th>
                {% if ns.show_vehicle %}
                <th style="width: 10%;">Vehicle<br>المركبة</th>
                {% endif %}
                <!-- Decrease amounts space -->
                 <th style="width: 15%;">Debit<br>القيمة المدينة</th>
                <th style="width: 15%;">Credit<br>القيمة الدائنة</th>
               
            </tr>
        </thead>
        <tbody>
            {% for account in doc.accounts %}
                <tr style="border: 3px solid {{ color }};">
                    <td>{{ account.idx }}</td>
                    <td>
                        <div>
                            Account: {{ account.account }}
                        </div>
                         {% if account.party %}
                          <div style="border-top: 1px dashed black;">
                             Party Name:
                          {% if account.party_type == "Employee" and account.party %}
                          {% set emp = frappe.db.get_value("Employee", account.party, "employee_name") %}
                          {{ emp or account.party }}
                          {% else %}
                          {{ account.party }}
                          {% endif %}
                         </div>
                        {% endif %}
                        {% if account.cost_center %}
                            <div style="border-top: 1px dashed black;">
                                Cost Center: {{ account.cost_center }}
                            </div>
                        {% endif %}
                        {% if account.project %}
                            <div style="border-top: 1px dashed black;">
                                Project: {{ frappe.db.get_value("Project", account.project, "project_name") }}
                            </div>
                        {% endif %}
                    </td>
                    <!-- If no remark, show empty string instead of None -->
                    <td style="text-align: center;">
                        {{ account.user_remark or "" }}
                    </td>
                    {% if ns.show_vehicle %}
                      <td style="text-align: center;">
                    {{ account.vehicle or "" }}
                      </td>
                    {% endif %}
                     <td style="text-align: center;">
                        {{ account.get_formatted("debit_in_account_currency", doc) or "" }}
                    </td>
                    <td style="text-align: center;">
                        {{ account.get_formatted("credit_in_account_currency", doc) or "" }}
                    </td>
                </tr>
            {% endfor %}
        </tbody>
    </table>
    
    <table class="pf-font-size-bg" style="width: 100%;">
        <tr>
            <td style="width: 70%;"></td>
            <td class="pf-color" style="width: 30%; text-align: right;">
                Total Credit: {{ doc.get_formatted("total_credit") }}
            </td>
        </tr>
        <tr>
            <td style="width: 70%;"></td>
            <td class="pf-color" style="width: 30%; text-align: right;">
                Total Debit: {{ doc.get_formatted("total_debit") }}
            </td>
        </tr>
    </table>
    
    <table class="pf-font-size-bg" style="width: 100%;">
        <tr>
            <td rowspan="3" style="width: 20%;">
                <img src="https://api.qrserver.com/v1/create-qr-code/?data={{ doc.name }}&size=120x120">
            </td>
            <td style="width: 10%;">
                
            </td>
            <td style="width: 25%; vertical-align: middle!important;">
                Reference # رقم المرجع:
            </td>
            <td style="width: 45%; vertical-align: middle!important;">
                {% if doc.cheque_no %}
                    {{ doc.cheque_no }}
                {% endif %}    
            </td>
        </tr>
        <tr>
            <td>
                
            </td>
            <td style="vertical-align: middle!important;">
                Reference Date التاريخ:
            </td>
            <td style="vertical-align: middle!important;">
                {{ doc.get_formatted("cheque_date") }}
            </td>
        </tr>
        <tr>
            <td>
                
            </td>
            <!-- Increase document note space here as well -->
            <td style="width: 20%; vertical-align: middle!important;">
                Remarks الملاحظات:
            </td>
            <td style="width: 60%; vertical-align: middle!important;">
                {{ doc.user_remark or "" }}
            </td>     
        </tr>
    </table>
    
    {% if footer %}
        <div class="text-center footer small">
            {{ footer }}
        </div>
    {% endif %}
    
</div>

{% set workflow_signatures = get_workflow_signatures_for_print(doc.doctype, doc.name) %}

{% if workflow_signatures and workflow_signatures|length > 0 %}
<h4 class="pf-font-size">Workflow Approvals</h4>

<table border="1" cellpadding="5" cellspacing="0" class="pf-font-size"
       style="width:100%; border-collapse: collapse; margin-top:10px;">
    <tr style="background:#f2f2f2;">
        <th>Step</th>
        <th>Approved By</th>
        <th>Email</th>
        <th>Date</th>
        <th>Signature</th>
    </tr>
    {% for step in workflow_signatures %}
    <tr>
        <td>{{ step.workflow_state }}</td>
        <td>{{ step.user }}</td>
        <td>{{ step.email }}</td>
        <td>{{ step.timestamp }}</td>
        <td style="text-align:center;">
            {% if step.signature %}
                <img src="{{ step.signature }}" style="max-width:100px;">
            {% else %}
                <span>No Signature</span>
            {% endif %}
        </td>
    </tr>
    {% endfor %}
</table>
{% endif %}
